list.expr:
sum by(version) (
    label_replace(vm_app_version{job=~"$job", instance=~"$instance", short_version!=""}, "version", "$1", "short_version", "(.*)")
    OR
    vm_app_version{job=~"$job", instance=~"$instance", short_version=""}
) 
unless 
(
    sum by(version) (
        label_replace(vm_app_version{job=~"$job", instance=~"$instance", short_version!=""}, "version", "$1", "short_version", "(.*)")
        OR
        vm_app_version{job=~"$job", instance=~"$instance", short_version=""}
    ) offset $__interval
)

targets.expr:
max(
max_over_time(vmauth_user_concurrent_requests_current{job=~"$job", instance=~"$instance", username=~"$user"}[$__rate_interval])
/ 
vmauth_user_concurrent_requests_capacity{job=~"$job", instance=~"$instance", username=~"$user"}
) by(username) > 0
